203	/**
204	 * Releases the lock file.
205	 */
206	export async function releaseLock(lockPath: string): Promise<void> {
207	  try {
208	    await fs.unlink(lockPath);
209	  } catch (error: unknown) {
210	    if (isNodeError(error) && error.code === 'ENOENT') {
211	      return; // Already removed
212	    }
213	    debugLogger.warn(
214	      `[MemoryService] Failed to release lock: ${error instanceof Error ? error.message : String(error)}`,
215	    );
216	  }
217	}
