}", "newString": "/**
 * Reads a session file into a ConversationRecord, supporting both the legacy
 * single-object `.json` format and the newer line-delimited `.jsonl` format
 * (metadata on the first line, one record per subsequent line).
 */
async function readSessionConversation(
  filePath: string,
): Promise<ConversationRecord | null> {
  if (filePath.endsWith('.jsonl')) {
    return await loadConversationRecord(filePath);
  }
  try {
    const content = await fs.readFile(filePath, 'utf-8');
    const parsed: unknown = JSON.parse(content);
    if (!isConversationRecord(parsed)) return null;
    return parsed;
  } catch {
    return null;
  }
}

/**
 * Scans the chats directory for eligible session files, sorted most-recent-first
 * by the `lastUpdated` timestamp found in the file content (not the filename),
 * capped at MAX_SESSION_INDEX_SIZE. Shared by buildSessionIndex.
 */
async function scanEligibleSessions(
  chatsDir: string,
): Promise<Array<{ conversation: ConversationRecord; filePath: string }>> {
  let allFiles: string[];
  try {
    allFiles = await fs.readdir(chatsDir);
  } catch {
    return [];
  }

  const sessionFiles = allFiles.filter(
    (f) =>
      f.startsWith(SESSION_FILE_PREFIX) &&
      (f.endsWith('.json') || f.endsWith('.jsonl')),
  );

  const results: Array<{ conversation: ConversationRecord; filePath: string }> =
    [];

  for (const file of sessionFiles) {
    const filePath = path.join(chatsDir, file);
    const conversation = await readSessionConversation(filePath);
    if (!conversation) continue;
    if (!shouldProcessConversation(conversation)) continue;
    results.push({ conversation, filePath });
  }

  // Sort by lastUpdated from the file content, most recent first.
  results.sort(
    (a, b) =>
      new Date(b.conversation.lastUpdated).getTime() -
      new Date(a.conversation.lastUpdated).getTime(),
  );

  return results.slice(0, MAX_SESSION_INDEX_SIZE);
