}", "newString": "export async function buildSessionIndex(
  chatsDir: string,
  state: ExtractionState,
): Promise<{
  sessionIndex: string;
  newSessionIds: string[];
  newSessionFiles: Array<{ sessionId: string; filePath: string }>;
}> {
  const processedSet = getProcessedSessionIds(state);
  const previousRunAt =
    state.runs.length > 0 ? state.runs[state.runs.length - 1].runAt : undefined;
  const previousRunAtMs = previousRunAt
    ? new Date(previousRunAt).getTime()
    : undefined;
  const eligible = await scanEligibleSessions(chatsDir);

  if (eligible.length === 0) {
    return { sessionIndex: '', newSessionIds: [], newSessionFiles: [] };
  }

  const lines: string[] = [];
  // Unprocessed sessions whose lastUpdated is newer than the previous run.
  const freshEntries: Array<{ sessionId: string; filePath: string }> = [];
  // Unprocessed sessions that are older than the previous run and would
  // otherwise starve — rotated into the current batch below.
  const staleEntries: Array<{ sessionId: string; filePath: string }> = [];

  for (const { conversation, filePath } of eligible) {
    const userMessageCount = conversation.messages.filter(
      (m) => m.type === 'user',
    ).length;
    const alreadyProcessed = processedSet.has(conversation.sessionId);
    const lastUpdatedMs = new Date(conversation.lastUpdated).getTime();

    // A session is "new" when it has been touched since the previous run.
    const isNew =
      previousRunAtMs === undefined ? true : lastUpdatedMs > previousRunAtMs;

    const status = isNew ? '[NEW]' : '[old]';
    const summary = conversation.summary ?? '(no summary)';
    lines.push(
      `${status} ${summary} (${userMessageCount} user msgs) — ${filePath}`,
    );

    if (alreadyProcessed) continue;
    const entry = { sessionId: conversation.sessionId, filePath };
    if (isNew) {
      freshEntries.push(entry);
    } else {
      staleEntries.push(entry);
    }
  }

  // Always offer the freshly-updated unprocessed sessions, and rotate older
  // unprocessed sessions into the batch as well so they don't starve when the
  // most recent files have already been handled by a previous run.
  const newSessionFiles = [...freshEntries, ...staleEntries];
  const newSessionIds = newSessionFiles.map((e) => e.sessionId);

  return {
    sessionIndex: lines.join('\n'),
    newSessionIds,
