    const allFiles = await fs.readdir(chatsDir);
    const sessionFiles = allFiles.filter(
      (f) =>
        f.startsWith(SESSION_FILE_PREFIX) &&
        (f.endsWith('.json') || f.endsWith('.jsonl')),
    );

    if (sessionFiles.length === 0) {
      debugLogger.debug('[SessionSummary] No session files found');
      return null;
    }

    // Never summarize the session that is currently active.
    const activeSessionId = config.getSessionId?.();

    // Stat files to order them by filesystem mtime. mtime is an upper bound on
    // the content `lastUpdated`, which lets us terminate the scan early once no
    // remaining file could possibly be newer than the best candidate found.
    const stats: Array<{ filePath: string; mtimeMs: number }> = [];
    for (const file of sessionFiles) {
      const filePath = path.join(chatsDir, file);
      try {
        const stat = await fs.stat(filePath);
        stats.push({ filePath, mtimeMs: stat.mtimeMs });
      } catch {
        // Skip files we can't stat.
      }
    }
    stats.sort((a, b) => b.mtimeMs - a.mtimeMs);

    let best: {
      filePath: string;
      lastUpdatedMs: number;
      conversation: ConversationRecord & { messageCount?: number };
    } | null = null;

    for (const { filePath, mtimeMs } of stats) {
      // Early termination: files are sorted by mtime descending and content
      // `lastUpdated` <= file mtime, so nothing remaining can beat `best`.
      if (best && best.lastUpdatedMs >= mtimeMs) break;

      const conversation = await loadConversationRecord(filePath, {
        metadataOnly: true,
      });
      if (!conversation) continue;

      // Skip the active session.
      if (activeSessionId && conversation.sessionId === activeSessionId) {
        continue;
      }

      const lastUpdatedMs = new Date(conversation.lastUpdated).getTime();
      if (!best || lastUpdatedMs > best.lastUpdatedMs) {
        best = { filePath, lastUpdatedMs, conversation };
      }
    }

    if (!best) {
      debugLogger.debug('[SessionSummary] No summarizable session found');
      return null;
    }

    const { conversation, filePath } = best;

    if (conversation.summary) {
      debugLogger.debug(
        '[SessionSummary] Most recent session already has summary',
      );
      return null;
