    if (messageCount <= MIN_MESSAGES_FOR_SUMMARY) {
      debugLogger.debug(
        `[SessionSummary] Most recent session has ${messageCount} message(s), skipping (need more than ${MIN_MESSAGES_FOR_SUMMARY})`,
